      meta.category === 'vegetation' ? VEGETATION_SET_TRIS : VARIANT_SET_TRIS;
    if (tris <= cap && sameAttributes) {
      set = {
        parts: [...groups].map(([material, list]) => {
          const geometry = mergeGeometries(list, false)!;
          geometry.computeBoundingSphere();
