  cr: Crown,
): void {
  const nrm = norm(cross(side, d));
  const base = b.count;
  for (const [su, sv] of [
    [0, 0],
    [1, 0],
    [1, 1],
    [0, 1],
  ]) {
    const p = madd(madd(o, side, (su * 2 - 1) * half), d, sv * length);
    // Cluster cards: u 0..0.5 of the atlas. Tiled cards: u >= 1, the dense leaf tile repeated every `tile` metres.
    const u = tile > 0 ? 1 + (su * 2 * half) / tile : su * 0.5;
    const v = tile > 0 ? (sv * length) / tile : sv;
    b.vertex(p, foliageNormal(cr, p, nrm), u, v, color, [
      order,
      w[0],
      w[1],
      occlusion(cr, p),
    ], tile > 0 ? [su, sv] : [-1, -1]);
  }
  b.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
}

